INSERT OR IGNORE INTO comments (disqus_id, post_slug, author_name, content, created_at) VALUES ('2806689076', '2016/07/easily-contribute-code-in-java-with-jitpack', 'Kelly Sheldrick', 'Thanks for explaining the importance of writing a micro library. It''s not something that I''ve looked at doing before, but it seems quite simple and very beneficial to your site, so I may as well give it a go. I''ll let you know how I go with using Jitpack and creating a micro library.', '2016-07-27T18:13:24Z');
INSERT OR IGNORE INTO comments (disqus_id, post_slug, author_name, content, created_at) VALUES ('2806699001', '2016/07/move-your-blog-from-blogger-to-metalsmith-today', 'Kelly Sheldrick', 'I tried using Blogger for my first ever website/ blog and I didn''t really like it either. How long have you been using metalsmith for? Is it specifically for technical writing? I''m also going to check out a couple of the plugins you mentioned as well.', '2016-07-27T18:17:14Z');
INSERT OR IGNORE INTO comments (disqus_id, post_slug, author_name, content, created_at) VALUES ('2806709944', '2015/10/angular-improve-website-performance', 'Kelly Sheldrick', 'Thanks for sharing this. I definitely prefer the pretty way. I think even I can work out how to destroy events that way. I actually think I may have these issues on my website, so I''ll definitely be trying your method to correct this. I''ve noticed that my website performance hasn''t been that great lately, so I''ll be willing to try almost anything to improve it.', '2016-07-27T18:22:17Z');
INSERT OR IGNORE INTO comments (disqus_id, post_slug, author_name, content, created_at) VALUES ('2843808348', '2015/10/angular-improve-website-performance', 'Rob Pocklington', 'This post is just click-bait.  It''s nothing new to realise you need to clear any background operations you may have when you destroy scope.  This article has a purpose, but it''s not in the title.', '2016-08-18T09:27:08Z');
INSERT OR IGNORE INTO comments (disqus_id, post_slug, author_name, content, created_at) VALUES ('2843975563', '2015/10/angular-improve-website-performance', 'guy mograbi', 'Hi @robpocklington:disqus
