INSERT OR IGNORE INTO comments (disqus_id, post_slug, author_name, content, created_at) VALUES ('2844004417', '2015/10/angular-improve-website-performance', 'guy mograbi', 'Thank you @kelly_sheldrick:disqus for your awesome feedback. hope everything will work well for you. keep me updated.', '2016-08-18T12:53:52Z');
INSERT OR IGNORE INTO comments (disqus_id, post_slug, author_name, content, created_at) VALUES ('2847509981', '2015/10/angular-improve-website-performance', 'Rob Pocklington', 'That''s cool - good on you for being open to it.  I''d call it "preventing memory leaks with background tasks by convention.  If you do things properly like test you cancel pending ops when on $destroy then this code won''t speed up your app at all.', '2016-08-19T23:10:15Z');
