INSERT OR IGNORE INTO comments (disqus_id, post_slug, author_name, content, created_at) VALUES ('3189918455', '2016/08/seperate-classpath-in-java', 'John Lonergan', 'Worse case is when the same class appears in multiple distinct jars, not versions of the same jar.<br>This is more insidious - look at the metrics jars from Codahale and Dropwizard with API incompatible versions of the same class in the two jars. <br>Gradle resolution isn''t going to help at all.<br>The gradle classpath-hell plugin can however detect this horror and report/break your build instead.', '2017-03-06T23:35:25Z');
