INSERT OR IGNORE INTO comments (disqus_id, post_slug, author_name, content, created_at) VALUES ('3624628974', '2013/08/extending-selenium-in-java', 'Francisco Burgos Valdés', 'Great post! Very usefull. Just I get with the doubt about how extend this for a list:<br>public class MyPage {  <br>    @FindBy(css="select#testme")  <br>    public List&lt;mograblogselect&gt; select;    <br>}', '2017-11-20T12:50:36Z');
INSERT OR IGNORE INTO comments (disqus_id, post_slug, author_name, content, created_at) VALUES ('3627639497', '2013/08/extending-selenium-in-java', 'guy mograbi', 'I am so happy you found my post useful.
There are many ways in which you can implement the list.
One of the possibilities is to add another annotation with more details. <br>Then you would need to add interceptor on a List implementation. <br>For example - lets decide your List feature only supports the method "get" - so you will have to intercept that and then return the WebElement wrapped in the handler.
Let me know if you feel you need more help, I''ll be happy to take a peak at snippets you have.
Also feel free to nag me at: <a href="https://gitter.im/GuyMograbi/mograblog" rel="nofollow noopener" target="_blank" title="https://gitter.im/GuyMograbi/mograblog">https://gitter.im/GuyMograb...</a>', '2017-11-22T05:26:11Z');
